    // Bring Simulator to focus
    system("open -a Simulator");
    usleep(500000); // Wait 500ms

    // Send right arrow key 3 times
    // Key code 124 is right arrow on macOS
    for (int i = 0; i < 3; i++) {
        CGEventRef keyDown = CGEventCreateKeyboardEvent(NULL, 124, true);
        CGEventPost(kCGHIDEventTap, keyDown);
        CFRelease(keyDown);

        usleep(100000); // 100ms

        CGEventRef keyUp = CGEventCreateKeyboardEvent(NULL, 124, false);
        CGEventPost(kCGHIDEventTap, keyUp);
        CFRelease(keyUp);

        usleep(300000); // 300ms between key presses
    }

    return 0;
}
